import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { BuildingEntity } from '../Entity/BuildingEntity';

export class GridSystem implements System {

    private _grid: Map<string, BuildingEntity> = new Map();

    onStart(_world: World): void {}
    onTick(): void {}

    private _key(x: number, y: number): string {
        return `${x},${y}`;
    }

    public isOccupied(x: number, y: number): boolean {
        return this._grid.has(this._key(x, y));
    }

    public getAt(x: number, y: number): BuildingEntity | undefined {
        return this._grid.get(this._key(x, y));
    }

    public occupy(b: BuildingEntity): void {
        this._grid.set(this._key(b.gridX, b.gridY), b);
    }

    public release(x: number, y: number): void {
        this._grid.delete(this._key(x, y));
    }

    public clear(): void {
        this._grid.clear();
    }
}